// final class ListNode { var val: Int; var next: ListNode?; init(_ v: Int, _ n: ListNode? = nil) { val = v; next = n } }
func removeNthFromEnd(_ head: ListNode?, _ n: Int) -> ListNode? {
    let dummy = ListNode(0, head)
    var lead: ListNode? = dummy, trail = dummy
    for _ in 0...n { lead = lead?.next }
    while lead != nil { lead = lead?.next; trail = trail.next! }
    trail.next = trail.next?.next
    return dummy.next
}
